      expect(existsSync(path.join(sub, 'run-0.pid')), 'the .pid stays').toBe(true);
      expect(existsSync(path.join(sub, 'run-0.jsonl')) || existsSync(path.join(sub, 'run-0.run.json')), 'no stream, no run.json').toBe(false);
